function t(k){return state.i18n[state.lang]?.[k]||state.i18n.en?.[k]||k}
function bn(){return state.lang==='bn'}
function validCanonicalId(id){return state.duas.some(r=>r.id===id)}
function isValidPersonalId(id){if(typeof id!=='string'||id.length>96)return false;return /^personal:(?:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|[a-z0-9]{1,16}(?:-[a-z0-9]{1,16}){4})$/i.test(id)}
