function jsArg(v){return esc(JSON.stringify(String(v??'')))}
function allPersonal(){return [...state.personalDuas.values()]}
function getRecord(id){return state.duas.find(r=>r.id===id)||state.personalDuas.get(id)||null}
function cleanSavedRecord(x){if(!x||typeof x.id!=='string')return null;const id=LEGACY_CANONICAL_ID_MAP[x.id]||x.id;if(!validCanonicalId(id))return null;return{id,title:String(x.title||'').trim().slice(0,120),note:String(x.note||'').trim().slice(0,4000),savedAt:Number(x.savedAt)||Date.now(),updatedAt:Number(x.updatedAt)||undefined,recordVersion:1}}
function mergeSavedRecords(a,b){if(!a)return b;if(!b)return a;const at=Number(a.updatedAt)||Number(a.savedAt)||0,bt=Number(b.updatedAt)||Number(b.savedAt)||0,newer=bt>=at?b:a,older=newer===b?a:b;const titles=[];for(const v of [newer.title,older.title])if(v&&!titles.includes(v))titles.push(v);const notes=[];for(const v of [newer.note,older.note])if(v&&!notes.includes(v))notes.push(v);return{id:newer.id,title:titles.join(' · ').slice(0,120),note:notes.join('\n\n').slice(0,4000),savedAt:Math.min(Number(a.savedAt)||Date.now(),Number(b.savedAt)||Date.now()),updatedAt:Math.max(Number(a.updatedAt)||0,Number(b.updatedAt)||0)||undefined,recordVersion:1}}
