async function persistSavedRecord(rec){const clean=cleanSavedRecord(rec);if(!clean)return;if(state.storageMode==='indexeddb'){await idbTxStore(SAVED_STORE,'readwrite',s=>s.put(clean))}else{state.savedRecords.set(clean.id,clean);writeFallbackSaved()}}
async function deleteSavedRecord(id){if(state.storageMode==='indexeddb'){await idbTxStore(SAVED_STORE,'readwrite',s=>s.delete(id))}else{state.savedRecords.delete(id);writeFallbackSaved()}}
async function replaceSavedRecords(records){const clean=records.map(cleanSavedRecord).filter(Boolean);if(state.storageMode==='indexeddb'){await new Promise((resolve,reject)=>{const tx=state.db.transaction(SAVED_STORE,'readwrite'),s=tx.objectStore(SAVED_STORE);s.clear();clean.forEach(x=>s.put(x));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('IndexedDB restore failed'));tx.onabort=()=>reject(tx.error||new Error('IndexedDB restore aborted'))})}state.savedRecords=new Map(clean.map(x=>[x.id,x]));state.saved=new Set(clean.map(x=>x.id));if(state.storageMode!=='indexeddb')writeFallbackSaved()}
