async function persistPersonalRecord(rec){const clean=cleanPersonalRecord(rec);if(!clean)throw new Error(t('personal_title_required'));if(state.storageMode==='indexeddb')await idbTxStore(PERSONAL_STORE,'readwrite',s=>s.put(clean));state.personalDuas.set(clean.id,clean);if(state.storageMode!=='indexeddb')writeFallbackPersonal();return clean}
async function deletePersonalRecord(id){if(state.storageMode==='indexeddb')await idbTxStore(PERSONAL_STORE,'readwrite',s=>s.delete(id));state.personalDuas.delete(id);if(state.storageMode!=='indexeddb')writeFallbackPersonal()}
async function replacePersonalRecords(records){const clean=records.map(cleanPersonalRecord).filter(Boolean);if(state.storageMode==='indexeddb'){await new Promise((resolve,reject)=>{const tx=state.db.transaction(PERSONAL_STORE,'readwrite'),s=tx.objectStore(PERSONAL_STORE);s.clear();clean.forEach(x=>s.put(x));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('IndexedDB restore failed'));tx.onabort=()=>reject(tx.error||new Error('IndexedDB restore aborted'))})}state.personalDuas=new Map(clean.map(x=>[x.id,x]));if(state.storageMode!=='indexeddb')writeFallbackPersonal()}
function writeFallbackPersonal(){localStorage.setItem('dua-personal-v1',JSON.stringify([...state.personalDuas.values()]))}
async function rewriteMigratedSavedStore(merged,retiredKeys){return new Promise((resolve,reject)=>{const tx=state.db.transaction(SAVED_STORE,'readwrite'),s=tx.objectStore(SAVED_STORE);for(const x of merged.values())s.put(x);for(const id of retiredKeys)s.delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('IndexedDB migration failed'));tx.onabort=()=>reject(tx.error||new Error('IndexedDB migration aborted'))})}
async function initPersonalStorage(){let migrated=false;try{state.db=await openPersonalDb();state.storageMode='indexeddb';const rawRows=await idbGetAllStore(SAVED_STORE),legacyIds=readJsonLocal('dua-saved',[]),legacyRows=readJsonLocal('dua-saved-v2',[]),merged=new Map(),retiredKeys=new Set();for(const raw of rawRows){const c=cleanSavedRecord(raw);if(!c)continue;mergeSavedInto(merged,c);if(raw?.id!==c.id){retiredKeys.add(raw.id);migrated=true}}for(const x of Array.isArray(legacyRows)?legacyRows:[]){const c=cleanSavedRecord(x);if(c){mergeSavedInto(merged,c);migrated=true}}for(const rawId of Array.isArray(legacyIds)?legacyIds:[]){const id=LEGACY_CANONICAL_ID_MAP[rawId]||rawId;if(validCanonicalId(id)){mergeSavedInto(merged,{id,title:'',note:'',savedAt:Date.now(),recordVersion:1});migrated=true}}if(migrated){await rewriteMigratedSavedStore(merged,retiredKeys);localStorage.removeItem('dua-saved');localStorage.removeItem('dua-saved-v2')}state.savedRecords=merged;state.saved=new Set(merged.keys());const personalRows=(await idbGetAllStore(PERSONAL_STORE)).map(cleanPersonalRecord).filter(Boolean);state.personalDuas=new Map(personalRows.map(x=>[x.id,x]))}catch(e){state.db=null;state.storageMode='localStorage';const legacyRows=readJsonLocal('dua-saved-v2',[]),legacyIds=readJsonLocal('dua-saved',[]),merged=new Map();for(const x of Array.isArray(legacyRows)?legacyRows:[]){const c=cleanSavedRecord(x);if(c)mergeSavedInto(merged,c)}for(const rawId of Array.isArray(legacyIds)?legacyIds:[]){const id=LEGACY_CANONICAL_ID_MAP[rawId]||rawId;if(validCanonicalId(id))mergeSavedInto(merged,{id,title:'',note:'',savedAt:Date.now(),recordVersion:1})}state.savedRecords=merged;state.saved=new Set(merged.keys());state.personalDuas=new Map((readJsonLocal('dua-personal-v1',[])||[]).map(cleanPersonalRecord).filter(Boolean).map(x=>[x.id,x]));writeFallbackSaved();writeFallbackPersonal()}await requestPersistentStorage(false);return migrated}
async function requestPersistentStorage(notify=true){try{if(navigator.storage?.persisted)state.persistence.persisted=!!(await navigator.storage.persisted());if(!state.persistence.persisted&&navigator.storage?.persist)state.persistence.persisted=!!(await navigator.storage.persist());state.persistence.supported=!!navigator.storage?.persist}catch{state.persistence.persisted=false}if(notify){render();toast(t('storage_checked'))}}
async function boot(){const core=['data/duas.json','data/themes.json','data/i18n.json','data/search-aliases.json'].map(u=>fetch(u).then(r=>r.json())),smart=fetch('data/smart-search-index.json').then(r=>r.ok?r.json():null).catch(()=>null);const [d,th,ii,al,si]=await Promise.all([...core,smart]);state.duas=d.records;state.themes=th;state.i18n=ii;state.aliases=al;state.smartIndex=si&&si.schema_version===1?si:null;const migrated=await initPersonalStorage();applyTheme(state.theme,false);document.documentElement.lang=state.lang;render();if(migrated)toast(t('migrated_saved'));registerSW();initNeuralAvailability();window.addEventListener('pageshow',()=>applyTheme(localStorage.getItem('dua-theme')||state.theme,false));document.addEventListener('visibilitychange',()=>{if(!document.hidden)applyTheme(localStorage.getItem('dua-theme')||state.theme,false)});}
function applyTheme(id,notify=true){if(!themeChrome[id])id='day';state.theme=id;localStorage.setItem('dua-theme',id);document.documentElement.dataset.theme=id;document.documentElement.style.backgroundColor=themeChrome[id];document.body&& (document.body.style.backgroundColor=themeChrome[id]);const m=$('#themeColor');if(m)m.content=themeChrome[id];document.documentElement.style.colorScheme=['day','sand','lavender'].includes(id)?'light':'dark';void document.documentElement.offsetHeight;requestAnimationFrame(()=>requestAnimationFrame(()=>{document.documentElement.style.backgroundColor='';if(document.body)document.body.style.backgroundColor=''}));if(notify){render();toast(t('theme_changed'))}}
function setLang(l){state.lang=l;localStorage.setItem('dua-lang',l);document.documentElement.lang=l;render();toast(t('language_changed'))}
function saveState(){localStorage.setItem('dua-display',JSON.stringify(state.display))}
async function toggleSave(id){if(!validCanonicalId(id))return;if(state.saved.has(id)){await deleteSavedRecord(id);state.saved.delete(id);state.savedRecords.delete(id);if(state.editSavedId===id)state.editSavedId=null}else{const rec={id,title:'',note:'',savedAt:Date.now(),recordVersion:1};await persistSavedRecord(rec);state.saved.add(id);state.savedRecords.set(id,rec)}render()}
let neuralQueryTimer=null,neuralQueryToken=0;
function neuralStatusCopy(){const n=state.neural;if(n.status==='ready')return `${t('neural_e5_name')} — ${t('neural_ready')}`;if(n.status==='preparing')return n.message||t('neural_preparing');if(n.status==='failed')return `${t('neural_failed')}${n.error?` — ${n.error}`:''}`;if(n.status==='cached')return `${t('neural_e5_name')} — ${t('neural_cached')}`;return t('neural_not_prepared')}
function neuralPanelHtml(){const n=state.neural,working=n.status==='preparing',ready=n.status==='ready';let action;if(working)action=`<button class="soft-btn" onclick="cancelNeuralPreparation()">${esc(t('cancel'))}</button>`;else if(ready||n.enabled)action=`<button class="soft-btn" onclick="clearNeuralSearch()">${esc(t('neural_remove'))}</button>`;else action=`<button class="soft-btn" onclick="prepareNeuralSearch()">${esc(n.status==='failed'?t('neural_retry'):t('neural_prepare'))}</button>`;const pct=working?`<div class="neural-progress"><span style="width:${Math.max(2,Math.min(100,Number(n.progress)||0))}%"></span></div>`:'';const latency=ready&&Number.isFinite(n.latencyMs)?` · ${Math.round(n.latencyMs)} ms`:'';const source=ready&&n.indexSource?` · ${t(n.indexSource==='shipped-precomputed'?'neural_index_precomputed':'neural_index_local')}`:'';const exportBtn=ready&&new URLSearchParams(location.search).get('preindex')==='1'?`<button class="soft-btn" onclick="exportE5PrecomputedIndex()">${esc(t('neural_export_index'))}</button>`:'';return `<div class="neural-panel" id="neuralPanel"><div class="neural-copy"><strong>${esc(t('neural_e5_name'))}</strong><span>${esc(neuralStatusCopy())}${latency}${esc(source)}</span>${pct}<span class="neural-model-meta">~118 MB · WASM · Web Worker · MIT</span></div><div class="neural-actions">${action}${exportBtn}</div></div>`}
function updateNeuralPanel(){const el=$('#neuralPanel');if(el)el.outerHTML=neuralPanelHtml()}
async function initNeuralAvailability(){if(!window.DODNeural){state.neural.status='failed';state.neural.error='runtime unavailable';updateNeuralPanel();return}try{const info=await DODNeural.inspect();state.neural.enabled=!!info.enabled;if(info.enabled&&(info.modelCached||info.staticIndex||info.vectorCached)){state.neural.status='cached';updateNeuralPanel();prepareNeuralSearch(true)}else{state.neural.status='idle';updateNeuralPanel()}}catch(e){state.neural.status='idle';updateNeuralPanel()}}
async function prepareNeuralSearch(auto=false){if(!window.DODNeural||state.neural.status==='preparing')return;if(state.neural.status==='ready')return;state.neural.enabled=true;state.neural.status='preparing';state.neural.error='';state.neural.progress=0;state.neural.message=auto?t('neural_preparing_cached'):t('neural_preparing');updateNeuralPanel();try{const out=await DODNeural.prepare(state.duas,{onProgress:p=>{state.neural.message=p.message||t('neural_preparing');state.neural.progress=Number(p.progress)||0;updateNeuralPanel()}});state.neural.status='ready';state.neural.enabled=true;state.neural.indexSource=out.indexSource||'';state.neural.message=t('neural_ready');state.neural.progress=100;state.neural.error='';updateNeuralPanel();if(state.query)scheduleNeuralQuery(state.query,true)}catch(e){if(e?.name==='AbortError'||e?.code==='DOD_ABORTED'){state.neural.status='idle';state.neural.error='';state.neural.message='';state.neural.progress=0;updateNeuralPanel();return}state.neural.status='failed';state.neural.error=String(e?.message||e).slice(0,240);state.neural.message=t('neural_failed');updateNeuralPanel();if(!auto)toast(t('neural_failed'))}}
function cancelNeuralPreparation(){if(!DODNeural.cancelPrepare?.())return;state.neural.status='idle';state.neural.error='';state.neural.message='';state.neural.progress=0;updateNeuralPanel()}
async function clearNeuralSearch(){if(!confirm(t('neural_remove_confirm')))return;neuralQueryToken++;if(neuralQueryTimer)clearTimeout(neuralQueryTimer);try{await DODNeural.clear()}catch{}state.neural={status:'idle',message:'',progress:0,query:'',scores:new Map(),latencyMs:null,error:'',enabled:false,indexSource:''};updateNeuralPanel();renderResults();toast(t('neural_removed'))}
async function exportE5PrecomputedIndex(){try{const data=await DODNeural.exportIndex(),blob=new Blob([JSON.stringify(data)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='DuaOnDevice-E5-Precomputed-199-q8.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);toast(t('neural_exported'))}catch(e){toast(String(e?.message||e))}}
function neuralMetric(id,q){if(state.neural.status!=='ready'||state.neural.query!==q)return{score:0,rank:0,boost:0};const x=state.neural.scores.get(id);if(!x)return{score:0,rank:0,boost:0};const rankBoost=[0,36,27,20,14,10,7,5,4][x.rank]||0,confidence=Math.max(0,Math.min(1,(x.score-.08)/.36));return{score:x.score,rank:x.rank,boost:rankBoost*(.72+.28*confidence)}}
function scheduleNeuralQuery(q,immediate=false){if(neuralQueryTimer)clearTimeout(neuralQueryTimer);const nq=String(q||'').trim();const token=++neuralQueryToken;if(state.neural.status!=='ready'||nq.length<3){state.neural.query='';state.neural.scores=new Map();state.neural.latencyMs=null;return}neuralQueryTimer=setTimeout(async()=>{try{const out=await DODNeural.search(nq,8);if(token!==neuralQueryToken||state.query!==q)return;const top=out.ranked?.[0]?.score??-Infinity,usable=Number.isFinite(top)&&top>=.10?out.ranked:[];state.neural.query=q;state.neural.scores=new Map(usable.map((x,i)=>[x.id,{score:Number(x.score),rank:i+1}]));state.neural.latencyMs=Number(out.latencyMs);renderResults();updateNeuralPanel()}catch(e){if(token!==neuralQueryToken)return;state.neural.error=String(e?.message||e).slice(0,240);state.neural.query='';state.neural.scores=new Map();updateNeuralPanel()}},immediate?0:180)}
function onSearchInput(v){state.query=v;state.neural.query='';state.neural.scores=new Map();renderResults();scheduleNeuralQuery(v)}
function clearSearchQuery(){neuralQueryToken++;if(neuralQueryTimer)clearTimeout(neuralQueryTimer);state.query='';state.neural.query='';state.neural.scores=new Map();state.neural.latencyMs=null;const q=$('#q');if(q)q.value='';renderResults();updateNeuralPanel()}
function normalize(s){return String(s||'').normalize('NFKC').toLowerCase().replace(/[’‘ʻʿ'"“”.,;:!?()\[\]{}\/\\\-_–—]/g,' ').replace(/\s+/g,' ').trim()}
function variantSearchText(r){try{return JSON.stringify(r.known_variants||[])}catch{return''}}
