function canonicalArabic(r){if(r.provenance==='quran'){if(state.arabicScript==='uthmani'&&r.arabic_uthmani)return r.arabic_uthmani;return r.arabic_indopak||r.arabic_uthmani||''}return r.arabic||r.arabic_indopak||''}
function canonicalArabicLabel(r){if(r.provenance==='quran')return state.arabicScript==='uthmani'?t('arabic_uthmani_label'):t('arabic_indopak_label');return t('arabic_source_wording')}
function searchTokens(s){return normalize(s).match(/[\p{L}\p{N}\p{M}]+/gu)?.filter(x=>x.length>1)||[]}
const SEARCH_STOPWORDS=new Set(['a','an','the','for','to','of','and','or','please','my','me','i','we','our','us','when','what','which','with','from','in','on','at','is','are','be','dua','duas','supplication','supplications','before','after','during','দোয়া','দোয়া','দুআ','দুয়া','জন্য','আমার','আমাকে','আমি','আমাদের','যখন','হলে','করার','করে','থেকে','আগে','পরে','পর','সময়','সময়']);
