function lexicalHay(r){return normalize([r.id,...(r.legacy_ids||[]),r.title_en,r.title_bn,r.source,r.source_type,r.arabic,r.arabic_indopak,r.arabic_uthmani,r.transliteration_en,r.meaning_en,r.transliteration_bn,r.meaning_bn,r.grade,variantSearchText(r),...(r.topics||[])].join(' '))}
