function directLexicalMatch(r,q){const nq=normalize(q);if(!nq)return false;const exact=[r.id,...(r.legacy_ids||[]),r.source,r.title_en,r.title_bn].some(x=>normalize(x)===nq);if(exact)return true;const strong=[r.title_en,r.title_bn,r.source,r.transliteration_en,r.transliteration_bn].join(' ');if(phraseIn(strong,nq))return true;const qt=scoringTokens(nq);if(qt.length>=4){const meanings=[r.meaning_en,r.meaning_bn].join(' ');if(phraseIn(meanings,nq))return true}return false}
const ALIAS_FILLERS=new Set(['a','an','the','is','are','please','my','me','i','we','our','us','dua','duas','supplication','দোয়া','দোয়া','দুআ','দুয়া','আমার','আমাকে','আমাদের']);
function aliasTokens(s){return searchTokens(s).filter(x=>!ALIAS_FILLERS.has(x))}
function aliasTokenNear(a,b){if(a===b)return true;if(a.length<3||b.length<3)return false;if((a.startsWith(b)||b.startsWith(a))&&Math.abs(a.length-b.length)<=3)return true;if(a.length>=5&&b.length>=5&&/^[a-z]+$/.test(a)&&/^[a-z]+$/.test(b)&&boundedEditDistance(a,b,1)<=1)return true;return false}
