function translitTokens(s){return foldTranslit(s).split(' ').filter(x=>x.length>=3)}
function translitSkeleton(s){return foldTranslit(s).replace(/[aeiou\s]/g,'').replace(/(.)\1+/g,'$1')}
function canonicalTranslitToken(x){if(x.length>4&&x[0]===x[1]&&!/[aeiou]/.test(x[0]))return x.slice(1);return x}
function boundedEditDistance(a,b,limit){if(Math.abs(a.length-b.length)>limit)return limit+1;let prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const cur=[i];let rowMin=i;for(let j=1;j<=b.length;j++){const v=Math.min(cur[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));cur[j]=v;if(v<rowMin)rowMin=v}if(rowMin>limit)return limit+1;prev=cur}return prev[b.length]}
function translitTokenMatch(a,b){a=canonicalTranslitToken(a);b=canonicalTranslitToken(b);if(a===b)return 1;if(a.length>=4&&b.length>=4&&(a.startsWith(b)||b.startsWith(a)||a.endsWith(b)||b.endsWith(a))&&Math.abs(a.length-b.length)<=2)return .92;if(a.length>=5&&b.length>=5){const limit=Math.min(a.length,b.length)<8?1:2,d=boundedEditDistance(a,b,limit);if(d<=limit)return d===1?.88:.78}return 0}
function translitSearchText(r){const out=[r.transliteration_en||''];for(const v of (r.known_variants||[]))if(v&&typeof v==='object'&&v.transliteration_en)out.push(v.transliteration_en);return out.join(' ')}
function translitScore(r,q){const qt=translitTokens(q);if(!qt.length)return 0;const text=translitSearchText(r),dt=translitTokens(text);if(!dt.length)return 0;const bests=qt.map(x=>{let best=0;for(const y of dt)best=Math.max(best,translitTokenMatch(x,y));return best}),matched=bests.filter(x=>x>=.78).length,cov=matched/qt.length,fq=foldTranslit(q).replace(/\s/g,''),fd=foldTranslit(text).replace(/\s/g,''),sq=translitSkeleton(q),sd=translitSkeleton(text);if(fq.length>=5&&fd.includes(fq))return 96+Math.min(20,fq.length/2);if(sq.length>=5&&sd.includes(sq))return 92+Math.min(18,sq.length);if(qt.length>=2&&cov===1)return 78+8*Math.min(qt.length,4)+bests.reduce((a,b)=>a+b,0)*3;if(qt.length>=3&&cov>=.67)return 48+20*cov;if(qt.length===1&&bests[0]>=.92&&qt[0].length>=5)return 52;return 0}
function smartAliasStrength(q,alias){if(!smartAliasMatch(q,alias))return 0;const na=normalize(alias),nq=normalize(q),n=searchTokens(na).length;return (phraseIn(nq,na)?100:45)+n*12+Math.min(na.length,40)}
function smartQueryContext(q){const si=state.smartIndex;if(!si||!q)return null;const dim=Number(si.dimensions)||0,v=new Array(dim).fill(0),counts=new Map();for(const tok of scoringTokens(q))counts.set(tok,(counts.get(tok)||0)+1);let hits=0;for(const [tok,n] of counts){const tv=si.term_vectors?.[tok];if(!Array.isArray(tv)||tv.length!==dim)continue;hits++;const w=1+Math.log(n);for(let i=0;i<dim;i++)v[i]+=w*Number(tv[i]||0)}let norm=Math.hypot(...v);const vector=norm?v.map(x=>x/norm):null,raw=[];for(const [id,c] of Object.entries(si.concepts||{})){let strength=0;for(const a of (c.aliases||[]))strength=Math.max(strength,smartAliasStrength(q,a));if(strength)raw.push({id,strength,priority:Number(c.priority??1),family:c.family||id})}let kept=raw;if(raw.length){const byFamily=new Map();for(const x of raw){const a=byFamily.get(x.family)||[];a.push(x);byFamily.set(x.family,a)}kept=[];for(const a of byFamily.values()){const maxP=Math.max(...a.map(x=>x.priority)),picks=a.filter(x=>x.priority===maxP);const maxS=Math.max(...picks.map(x=>x.strength));kept.push(...picks.filter(x=>x.strength>=maxS*.72))}const globalP=Math.max(...kept.map(x=>x.priority));kept=kept.filter(x=>x.priority>=Math.max(0,globalP-1))}const concepts=kept.map(x=>x.id),exclusive=concepts.filter(id=>!!si.concepts?.[id]?.exclusive);return{vector,concepts,exclusive,hits}}
function smartCanonicalMetrics(r,q,ctx){const lex=lexicalScore(r,q),translit=translitScore(r,q),neural=neuralMetric(r.id,q);if(!ctx||!state.smartIndex)return{score:lex+translit+neural.boost,lex,translit,matched:0,exclusiveMatched:0,sim:0,neural:neural.score,neuralRank:neural.rank};const si=state.smartIndex,rc=new Set(si.record_concepts?.[r.id]||[]),matched=ctx.concepts.filter(x=>rc.has(x)),exclusiveMatched=(ctx.exclusive||[]).filter(x=>rc.has(x)).length;let conceptBoost=0;for(const x of matched)conceptBoost+=Number(si.concepts?.[x]?.weight)||28;if(matched.length>1)conceptBoost+=14*(matched.length-1);let sim=0;if(ctx.vector){const dv=si.doc_vectors?.[r.id];if(Array.isArray(dv)&&dv.length===ctx.vector.length)for(let i=0;i<dv.length;i++)sim+=ctx.vector[i]*Number(dv[i]||0)}let semantic=sim>.12?(sim-.12)*42:0;if(ctx.concepts.length&&!matched.length)semantic=sim>.30?(sim-.30)*28:0;let score=lex+translit+conceptBoost+semantic+neural.boost;if(!lex&&!translit&&!matched.length&&!neural.boost){const need=ctx.concepts.length?.34:.20;if(sim<need)score=0}return{score,lex,translit,matched:matched.length,exclusiveMatched,sim,neural:neural.score,neuralRank:neural.rank}}
function selectRelevantCanonical(rows,q,ctx){rows=rows.filter(x=>x.m.score>0).sort((a,b)=>b.m.score-a.m.score||a.r.id.localeCompare(b.r.id));if(!rows.length)return[];if(ctx?.exclusive?.length){const gated=rows.filter(x=>x.m.exclusiveMatched>0);if(gated.length)rows=gated}const top=rows[0].m.score,direct=rows.filter(x=>x.m.translit>=52||directLexicalMatch(x.r,q));let selected=[];if(ctx?.concepts?.length){const maxMatched=Math.max(...rows.map(x=>x.m.matched));if(maxMatched>=2){selected=rows.filter(x=>x.m.matched===maxMatched);selected.push(...rows.filter(x=>x.m.matched>0&&x.m.matched<maxMatched&&x.m.score>=top*.72))}else if(maxMatched===1){selected=rows.filter(x=>x.m.matched>=1);if(selected.length>16){const floor=Math.max(12,top*.42);selected=selected.filter(x=>x.m.score>=floor)}}else{const floor=Math.max(8,top*.35);selected=rows.filter(x=>x.m.score>=floor)}}else{const floor=Math.max(8,top*.30);selected=rows.filter(x=>x.m.score>=floor)}const byId=new Map(selected.map(x=>[x.r.id,x]));for(const x of direct)byId.set(x.r.id,x);selected=[...byId.values()].sort((a,b)=>b.m.score-a.m.score||a.r.id.localeCompare(b.r.id));if(selected.length>30){const floor=Math.max(12,top*.55);selected=selected.filter(x=>x.m.score>=floor||x.m.translit>=52||directLexicalMatch(x.r,q))}return selected}
function score(r,q){return lexicalScore(r,q)}
function filteredCanonical(){let a=state.duas;if(state.filter!=='all')a=a.filter(x=>x.provenance===state.filter);if(state.query){const ctx=smartQueryContext(state.query),rows=a.map(r=>({r,m:smartCanonicalMetrics(r,state.query,ctx)}));a=selectRelevantCanonical(rows,state.query,ctx).map(x=>x.r)}return a}
function filteredPersonal(){if(state.filter!=='all')return[];let a=allPersonal();if(state.query)a=a.map(x=>[lexicalScore(x,state.query),x]).filter(x=>x[0]>0).sort((a,b)=>b[0]-a[0]||(b[1].updatedAt||0)-(a[1].updatedAt||0)).map(x=>x[1]);else a.sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));return a}
function prov(r){if(r.origin==='personal')return t('personal_dua');return r.provenance==='quran'?t('quran'):r.provenance==='sunnah'?t('sunnah'):t('athar')}
function card(r){return `<article class="card"><div class="card-row"><button class="card-main" style="text-align:left;border:0;background:transparent;padding:0;color:inherit" onclick="openDua(${jsArg(r.id)})"><div class="badge-row"><span class="badge prov">${esc(prov(r))}</span><span class="badge">${esc(r.id)}</span></div><h4>${esc(bn()?r.title_bn:r.title_en)}</h4><p>${esc(r.source)}</p></button><button class="save-btn ${state.saved.has(r.id)?'saved':''}" aria-label="${esc(state.saved.has(r.id)?t('unsave'):t('save'))}" onclick="toggleSave('${r.id}')">${state.saved.has(r.id)?'★':'☆'}</button></div></article>`}
function personalCard(r){const title=(bn()?r.title_bn:r.title_en)||r.title_en||r.title_bn;const preview=(bn()?r.meaning_bn:r.meaning_en)||r.meaning_en||r.meaning_bn||r.arabic_indopak||r.source||t('personal_no_preview');return `<article class="card personal-record"><button class="card-main" style="text-align:left;border:0;background:transparent;padding:0;color:inherit;width:100%" onclick="openDua(${jsArg(r.id)})"><div class="badge-row"><span class="badge personal-badge">${esc(t('personal_dua'))}</span></div><h4>${esc(title)}</h4><p>${esc(preview)}</p></button></article>`}
function shell(content){return `<div class="app-shell"><header class="top-safe"><div class="topbar"><div class="brand"><h1>${esc(t('app'))}</h1><p>${esc(t('maker'))}</p></div><span class="status">${esc(t('ready'))}</span></div></header><main class="workspace"><div class="content">${content}</div></main></div>${nav()}`}
function nav(){const items=[['search','⌕','search'],['browse','▦','browse'],['saved','☆','saved'],['guide','?','guide'],['settings','⚙','settings']];return `<nav class="bottom-nav">${items.map(([id,ic,key])=>`<button class="nav-btn ${state.tab===id&&!state.detail?'active':''}" onclick="go('${id}')"><span class="nav-icon">${ic}</span><span>${esc(t(key))}</span></button>`).join('')}</nav>`}
function renderSearch(){const c=filteredCanonical(),p=filteredPersonal();return `<section class="hero"><h2>${esc(t('search'))}</h2><p>${esc(t('tagline'))}</p></section><div class="searchbox"><span>⌕</span><input id="q" value="${esc(state.query)}" placeholder="${esc(t('search_placeholder'))}" oninput="onSearchInput(this.value)"><button class="icon-btn" onclick="clearSearchQuery()">${esc(t('clear'))}</button></div><div class="hint">${esc(t('smart_hint'))}</div>${filters()}<div id="results">${resultsHtml(c,p)}</div>`}
function filters(){return `<div class="filters">${[['all','all'],['quran','quran'],['sunnah','sunnah'],['athar','athar']].map(([id,key])=>`<button class="chip ${state.filter===id?'active':''}" onclick="state.filter='${id}';render()">${esc(t(key))}</button>`).join('')}</div>`}
function resultsHtml(c,p){const canonical=`<div class="section-head"><h3>${esc(t('verified_results'))}</h3><span>${c.length} ${esc(t('results'))}</span></div>${c.length?`<div class="list">${c.map(card).join('')}</div>`:`<div class="empty compact"><h3>${esc(t('no_results'))}</h3></div>`}`;const personal=state.filter==='all'?`<div class="section-head personal-results-head"><h3>${esc(t('your_duas'))}</h3><span>${p.length} ${esc(t('results'))}</span></div>${p.length?`<div class="list">${p.map(personalCard).join('')}</div>`:`<div class="empty compact"><p>${esc(t('personal_search_empty'))}</p></div>`}`:'';return canonical+personal}
function renderResults(){const el=$('#results');if(el)el.innerHTML=resultsHtml(filteredCanonical(),filteredPersonal())}
function browseOriginToggle(){return `<div class="segmented browse-origin"><button class="${state.browseOrigin==='canonical'?'active':''}" onclick="setBrowseOrigin('canonical')">${esc(t('canonical_duas'))}</button><button class="${state.browseOrigin==='personal'?'active':''}" onclick="setBrowseOrigin('personal')">${esc(t('my_duas'))}</button></div>`}
function renderBrowse(){if(state.personalEditorId!==null)return renderPersonalEditor(state.personalEditorId);if(state.browseOrigin==='personal')return renderMyDuas();const a=state.filter==='all'?state.duas:state.duas.filter(x=>x.provenance===state.filter);return `<section class="hero"><h2>${esc(t('catalog'))}</h2><p>${esc(t('catalog_sub'))}</p></section>${browseOriginToggle()}${filters()}<div class="list">${a.map(card).join('')}</div>`}
function renderMyDuas(){const a=allPersonal().sort((x,y)=>(y.updatedAt||0)-(x.updatedAt||0));return `<section class="hero"><h2>${esc(t('my_duas'))}</h2><p>${esc(t('my_duas_desc'))}</p></section>${browseOriginToggle()}<div class="personal-toolbar"><button class="primary-btn" onclick="openPersonalEditor('new')">＋ ${esc(t('add_dua'))}</button></div>${a.length?`<div class="list">${a.map(personalManageCard).join('')}</div>`:`<div class="empty"><div class="big">＋</div><h3>${esc(t('my_duas_empty'))}</h3><p>${esc(t('my_duas_empty_body'))}</p></div>`}`}
function personalManageCard(r){const title=(bn()?r.title_bn:r.title_en)||r.title_en||r.title_bn;return `<article class="card personal-record"><button class="card-main" style="text-align:left;border:0;background:transparent;padding:0;color:inherit;width:100%" onclick="openDua(${jsArg(r.id)})"><div class="badge-row"><span class="badge personal-badge">${esc(t('personal_dua'))}</span></div><h4>${esc(title)}</h4><p>${esc(r.source||t('no_personal_source'))}</p></button><div class="saved-actions"><button class="soft-btn" onclick="openPersonalEditor(${jsArg(r.id)})">${esc(t('edit'))}</button><button class="soft-btn danger" onclick="removePersonalDua(${jsArg(r.id)})">${esc(t('delete'))}</button></div></article>`}
function personalField(id,label,value='',type='input',placeholder=''){return `<label class="personal-field"><span>${esc(label)}</span>${type==='textarea'?`<textarea id="${id}" rows="4" placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input id="${id}" value="${esc(value)}" placeholder="${esc(placeholder)}">`}</label>`}
function renderPersonalEditor(id){const r=id==='new'?null:state.personalDuas.get(id);const topics=(r?.topics||[]).join(', '),sourceUrl=r?.source_links?.[0]?.url||'';return `<div class="backbar"><button onclick="closePersonalEditor()">← ${esc(t('back'))}</button></div><section class="hero"><h2>${esc(r?t('edit_personal_dua'):t('add_dua'))}</h2><p>${esc(t('personal_authority_notice'))}</p></section><div class="personal-form"><div class="personal-form-section"><h3>${esc(t('titles'))}</h3>${personalField('pd-title-en',t('title_en'),r?.title_en||'','input',t('optional_if_bangla_title'))}${personalField('pd-title-bn',t('title_bn'),r?.title_bn||'','input',t('optional_if_english_title'))}</div><div class="personal-form-section"><h3>${esc(t('dua_text'))}</h3>${personalField('pd-arabic',t('arabic'),r?.arabic_indopak||'','textarea',t('optional'))}${personalField('pd-en-translit',t('show_en_translit'),r?.transliteration_en||'','textarea',t('optional'))}${personalField('pd-en-meaning',t('show_en_meaning'),r?.meaning_en||'','textarea',t('optional'))}${personalField('pd-bn-translit',t('show_bn_translit'),r?.transliteration_bn||'','textarea',t('optional'))}${personalField('pd-bn-meaning',t('show_bn_meaning'),r?.meaning_bn||'','textarea',t('optional'))}</div><div class="personal-form-section"><h3>${esc(t('personal_source'))}</h3>${personalField('pd-source',t('source_reference'),r?.source||'','input',t('optional'))}${personalField('pd-source-url',t('source_link'),sourceUrl,'input','https://…')}${personalField('pd-topics',t('topics_tags'),topics,'input',t('comma_separated'))}<p class="personal-form-note">${esc(t('source_entered_notice'))}</p></div><div class="saved-actions"><button class="primary-btn" onclick="savePersonalDua(${jsArg(r?.id||'new')})">${esc(t('save_dua'))}</button><button class="soft-btn" onclick="closePersonalEditor()">${esc(t('cancel'))}</button></div></div>`}
function setBrowseOrigin(x){state.browseOrigin=x;state.personalEditorId=null;state.filter='all';render()}
function openPersonalEditor(id){state.tab='browse';state.browseOrigin='personal';state.personalEditorId=id;state.detail=null;render();setTimeout(()=>$('.workspace')?.scrollTo(0,0),0)}
function closePersonalEditor(){state.personalEditorId=null;render()}
async function savePersonalDua(id){const now=Date.now(),existing=id==='new'?null:state.personalDuas.get(id),title_en=$('#pd-title-en')?.value||'',title_bn=$('#pd-title-bn')?.value||'';if(!title_en.trim()&&!title_bn.trim()){toast(t('personal_title_required'));return}const sourceUrl=$('#pd-source-url')?.value||'';if(sourceUrl.trim()&&!safeSourceUrl(sourceUrl.trim())){toast(t('source_link_invalid'));return}const topics=String($('#pd-topics')?.value||'').split(',').map(x=>x.trim()).filter(Boolean);const raw={...(existing||{}),id:existing?.id||makePersonalId(),origin:'personal',title_en,title_bn,arabic_indopak:$('#pd-arabic')?.value||'',transliteration_en:$('#pd-en-translit')?.value||'',meaning_en:$('#pd-en-meaning')?.value||'',transliteration_bn:$('#pd-bn-translit')?.value||'',meaning_bn:$('#pd-bn-meaning')?.value||'',source:$('#pd-source')?.value||'',source_links:sourceUrl.trim()?[{label:'',url:sourceUrl.trim()}]:[],topics,createdAt:existing?.createdAt||now,updatedAt:now};try{const clean=await persistPersonalRecord(raw);state.personalEditorId=null;state.detail=clean.id;render();toast(t('personal_dua_saved'))}catch(e){toast(e?.message||t('personal_save_failed'))}}
async function removePersonalDua(id){const r=state.personalDuas.get(id);if(!r)return;if(!confirm(t('delete_personal_confirm')))return;await deletePersonalRecord(id);if(state.detail===id)state.detail=null;if(state.personalEditorId===id)state.personalEditorId=null;render();toast(t('personal_dua_deleted'))}
function savedCard(r){const meta=state.savedRecords.get(r.id)||{id:r.id,title:'',note:''},editing=state.editSavedId===r.id,hasMeta=!!(meta.title||meta.note);return `<article class="card saved-record"><div class="card-row"><button class="card-main" style="text-align:left;border:0;background:transparent;padding:0;color:inherit" onclick="openDua(${jsArg(r.id)})"><div class="badge-row"><span class="badge prov">${esc(prov(r))}</span><span class="badge">${esc(r.id)}</span></div>${meta.title?`<h4 class="personal-title">${esc(meta.title)}</h4><p class="canonical-title">${esc(bn()?r.title_bn:r.title_en)}</p>`:`<h4>${esc(bn()?r.title_bn:r.title_en)}</h4>`}<p>${esc(r.source)}</p>${meta.note?`<div class="personal-note-preview">${esc(meta.note)}</div>`:''}</button></div>${editing?noteEditor(r,meta):`<div class="saved-actions"><button class="soft-btn" onclick="editSaved('${r.id}')">${esc(t(hasMeta?'edit_note':'add_note'))}</button><button class="soft-btn danger" onclick="toggleSave('${r.id}')">${esc(t('remove'))}</button></div>`}</article>`}
function noteEditor(r,meta){return `<div class="note-editor"><label><span>${esc(t('personal_title'))}</span><input id="noteTitle-${r.id}" maxlength="120" value="${esc(meta.title||'')}" placeholder="${esc(t('personal_title_placeholder'))}"></label><label><span>${esc(t('personal_note'))}</span><textarea id="noteBody-${r.id}" maxlength="4000" rows="5" placeholder="${esc(t('personal_note_placeholder'))}">${esc(meta.note||'')}</textarea></label><div class="saved-actions"><button class="primary-btn" onclick="savePersonalNote('${r.id}')">${esc(t('save_note'))}</button><button class="soft-btn" onclick="cancelSavedEdit()">${esc(t('cancel'))}</button>${meta.title||meta.note?`<button class="soft-btn danger" onclick="clearPersonalNote('${r.id}')">${esc(t('clear_note'))}</button>`:''}</div></div>`}
function renderSaved(){const a=state.duas.filter(x=>state.saved.has(x.id)).sort((a,b)=>(state.savedRecords.get(b.id)?.savedAt||0)-(state.savedRecords.get(a.id)?.savedAt||0));return `<section class="hero"><h2>${esc(t('saved'))}</h2><p>${esc(t('personal_data_desc'))}</p></section>${a.length?`<div class="list">${a.map(savedCard).join('')}</div>`:`<div class="empty"><div class="big">☆</div><h3>${esc(t('saved_empty'))}</h3><p>${esc(t('saved_empty_body'))}</p></div>`}`}
function editSaved(id){state.editSavedId=id;render()}
function cancelSavedEdit(){state.editSavedId=null;render()}
async function savePersonalNote(id){const old=state.savedRecords.get(id);if(!old)return;const title=$(`#noteTitle-${id}`)?.value||'',note=$(`#noteBody-${id}`)?.value||'',rec={...old,title:title.trim().slice(0,120),note:note.trim().slice(0,4000),updatedAt:Date.now()};await persistSavedRecord(rec);state.savedRecords.set(id,rec);state.editSavedId=null;render();toast(t('note_updated'))}
async function clearPersonalNote(id){const old=state.savedRecords.get(id);if(!old)return;const rec={...old,title:'',note:'',updatedAt:Date.now()};await persistSavedRecord(rec);state.savedRecords.set(id,rec);state.editSavedId=null;render();toast(t('note_cleared'))}
function renderGuide(){return `<section class="hero"><h2>${esc(t('guide'))}</h2><p>${esc(t('tagline'))}</p></section><div class="guide-card"><h3>${esc(t('guide_title'))}</h3><p>${esc(t('guide_body'))}</p></div><div class="guide-card"><h3>${esc(t('trust_title'))}</h3><p>${esc(t('trust_body'))}</p></div><div class="guide-card"><h3>${esc(t('build_scope'))}</h3><p>${esc(t('build_scope_body'))}</p></div><div class="guide-card"><h3>${esc(t('neural_title'))}</h3><p>${esc(t('neural_guide'))}</p><p class="guide-fine">${esc(t('neural_license_guide'))}</p></div><div class="guide-card"><h3>${esc(t('neural_license_title'))}</h3><div class="source-links"><a href="https://huggingface.co/intfloat/multilingual-e5-small" target="_blank" rel="noopener noreferrer">E5 Small — MIT</a><a href="MODEL-LICENSES.txt" target="_blank" rel="noopener noreferrer">DuaOnDevice model notices</a></div></div><div class="guide-card"><h3>${esc(t('my_duas'))}</h3><p>${esc(t('my_duas_guide'))}</p></div><div class="guide-card quran-sources-guide"><h3>${esc(t('quran_sources_title'))}</h3><p>${esc(t('quran_sources_guide'))}</p></div><div class="guide-card"><h3>${esc(t('offline'))}</h3><p>${esc(t('offline_desc'))}</p></div>`}
function swatch(th){return `<span class="theme-swatch" style="--sw1:${th.bg};--sw2:${th.accent}"></span>`}
function persistenceText(){if(state.persistence.persisted)return t('persistent_granted');if(state.persistence.supported)return t('persistent_managed');return t('persistent_unavailable')}
function storageSummary(){return `${state.saved.size} ${t('saved')} · ${state.personalDuas.size} ${t('my_duas')} · ${state.storageMode==='indexeddb'?t('indexeddb'):t('local_fallback')} · ${persistenceText()}`}
function renderSettings(){const langButtons=`<div class="segmented"><button class="${state.lang==='en'?'active':''}" onclick="setLang('en')">English</button><button class="${state.lang==='bn'?'active':''}" onclick="setLang('bn')">বাংলা</button></div>`;const toggles=[['enTranslit','show_en_translit'],['enMeaning','show_en_meaning'],['bnTranslit','show_bn_translit'],['bnMeaning','show_bn_meaning']];return `<section class="hero"><h2>${esc(t('settings'))}</h2><p>${esc(t('status'))}</p></section><div class="settings-group"><h3>${esc(t('language'))}</h3><div class="setting-card"><div class="setting-row"><div class="setting-copy"><strong>${esc(t('language'))}</strong><span>English / বাংলা</span></div>${langButtons}</div></div></div><div class="settings-group"><h3>${esc(t('appearance'))}</h3><div class="themes">${Object.entries(state.themes).map(([id,th])=>`<button class="theme-btn ${state.theme===id?'active':''}" onclick="applyTheme('${id}')">${swatch(th)}${esc(bn()?th.label_bn:th.label)}</button>`).join('')}</div></div><div class="settings-group"><h3>${esc(t('display'))}</h3><div class="setting-card">${toggles.map(([id,key])=>`<div class="setting-row"><div class="setting-copy"><strong>${esc(t(key))}</strong></div><button class="switch ${state.display[id]?'on':''}" aria-label="${esc(t(key))}" onclick="state.display.${id}=!state.display.${id};saveState();render()"></button></div>`).join('')}<div class="setting-row"><div class="setting-copy"><strong>${esc(t('arabic_script'))}</strong><span>${esc(t('arabic_script_desc'))}</span></div><div class="segmented"><button class="${state.arabicScript==='indopak'?'active':''}" onclick="setArabicScript('indopak')">${esc(t('indopak'))}</button><button class="${state.arabicScript==='uthmani'?'active':''}" onclick="setArabicScript('uthmani')">${esc(t('uthmani'))}</button></div></div></div></div><div class="settings-group"><h3>${esc(t('neural_title'))}</h3><p class="neural-model-note">${esc(t('neural_settings_desc'))}</p>${neuralPanelHtml()}</div><div class="settings-group"><h3>${esc(t('offline'))}</h3><div class="setting-card"><div class="setting-row"><div class="setting-copy"><strong>${esc(t('offline'))}</strong><span>${esc(t('offline_desc'))}</span></div></div><div class="setting-row"><div class="setting-copy"><strong>${esc(t('privacy'))}</strong><span>${esc(t('privacy_desc'))}</span></div></div></div></div><div class="settings-group"><h3>${esc(t('personal_data'))}</h3><div class="setting-card"><div class="setting-row"><div class="setting-copy"><strong>${esc(t('storage_status'))}</strong><span>${esc(storageSummary())}</span></div><button class="soft-btn" onclick="requestPersistentStorage(true)">${esc(t('check_storage'))}</button></div><div class="setting-row"><div class="setting-copy"><strong>${esc(t('backup'))}</strong><span>${esc(t('backup_desc_v2'))}</span></div><button class="soft-btn" onclick="downloadPersonalBackup()">${esc(t('create_backup'))}</button></div><div class="setting-row"><div class="setting-copy"><strong>${esc(t('restore'))}</strong><span>${esc(t('restore_desc_v2'))}</span></div><button class="soft-btn" onclick="$('#restoreBackupFile').click()">${esc(t('restore_backup'))}</button><input class="file-input" id="restoreBackupFile" type="file" accept="application/json,.json" onchange="restorePersonalBackup(this)"></div></div></div>`}
function safeSourceUrl(u){try{const x=new URL(String(u||''));return ['https:','http:'].includes(x.protocol)?x.href:''}catch{return ''}}
function sourceLinks(r){if(!Array.isArray(r.source_links)||!r.source_links.length)return r.origin==='personal'?`<span class="source-link-pending">${esc(r.source?t('source_entered_by_you'):t('no_personal_source'))}</span>`:`<span class="source-link-pending">${esc(t('no_source_link'))}</span>`;const links=r.source_links.map(x=>[safeSourceUrl(x.url),x.label]).filter(x=>x[0]);if(!links.length)return r.origin==='personal'?`<span class="source-link-pending">${esc(r.source?t('source_entered_by_you'):t('no_personal_source'))}</span>`:`<span class="source-link-pending">${esc(t('no_source_link'))}</span>`;return `<div class="source-links">${links.map(([url,label])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label||(r.origin==='personal'?t('open_personal_source_link'):t('source_online')))}</a>`).join('')}</div>`}
function quranCreditsHtml(r){if(r?.provenance!=='quran')return'';return `<div class="quran-credit"><strong>${esc(t('quran_sources_title'))}</strong><span>${esc(t('quran_sources_detail'))}</span></div>`}
function quranFootnotesHtml(r,lang){if(r?.provenance!=='quran'||!Array.isArray(r.quran_source_segments))return'';const key=lang==='bn'?'meaning_bn_footnotes':'meaning_en_footnotes',notes=r.quran_source_segments.map(s=>({ref:String(s.ref||r.source||''),note:typeof s[key]==='string'?s[key]:''})).filter(x=>x.note.trim());if(!notes.length)return'';const title=lang==='bn'?t('translation_notes_bn'):t('translation_notes_en');return `<details class="quran-footnotes"><summary>${esc(title)} (${notes.length})</summary><div class="quran-footnote-list">${notes.map(x=>`<div class="quran-footnote-item"><strong>${esc(x.ref)}</strong><p${lang==='bn'?' lang="bn" class="bn-text quran-footnote-text"':' class="quran-footnote-text"'}>${esc(x.note)}</p></div>`).join('')}</div></details>`}
function optionalContent(r){const items=[];if(r.arabic_indopak)items.push(`<div class="info personal-text"><h4>${esc(t('arabic'))}</h4><p lang="ar" dir="rtl" class="personal-arabic arabic-source">${esc(r.arabic_indopak)}</p></div>`);if(state.display.enTranslit&&r.transliteration_en)items.push(`<div class="info personal-text"><h4>${esc(t('show_en_translit'))}</h4><p>${esc(r.transliteration_en)}</p></div>`);if(state.display.enMeaning&&r.meaning_en)items.push(`<div class="info personal-text"><h4>${esc(t('show_en_meaning'))}</h4><p>${esc(r.meaning_en)}</p></div>`);if(state.display.bnTranslit&&r.transliteration_bn)items.push(`<div class="info personal-text"><h4>${esc(t('show_bn_translit'))}</h4><p lang="bn" class="bn-text">${esc(r.transliteration_bn)}</p></div>`);if(state.display.bnMeaning&&r.meaning_bn)items.push(`<div class="info personal-text"><h4>${esc(t('show_bn_meaning'))}</h4><p lang="bn" class="bn-text">${esc(r.meaning_bn)}</p></div>`);return items.join('')}
function canonicalContent(r){const items=[],ar=canonicalArabic(r),arMode=r.provenance==='quran'?(state.arabicScript==='uthmani'?'arabic-uthmani':'arabic-indopak'):'arabic-source';if(ar)items.push(`<div class="info canonical-text"><h4>${esc(canonicalArabicLabel(r))}</h4><p lang="ar" dir="rtl" class="canonical-arabic ${arMode}">${esc(ar)}</p></div>`);if(state.display.enTranslit&&r.transliteration_en)items.push(`<div class="info canonical-text"><h4>${esc(t('show_en_translit'))}</h4><p>${esc(r.transliteration_en)}</p></div>`);if(state.display.enMeaning&&r.meaning_en)items.push(`<div class="info canonical-text"><h4>${esc(t('show_en_meaning'))}</h4><p>${esc(r.meaning_en)}</p>${quranFootnotesHtml(r,'en')}</div>`);if(state.display.bnTranslit&&r.transliteration_bn)items.push(`<div class="info canonical-text"><h4>${esc(t('show_bn_translit'))}</h4><p lang="bn" class="bn-text">${esc(r.transliteration_bn)}</p></div>`);if(state.display.bnMeaning&&r.meaning_bn)items.push(`<div class="info canonical-text"><h4>${esc(t('show_bn_meaning'))}</h4><p lang="bn" class="bn-text">${esc(r.meaning_bn)}</p>${quranFootnotesHtml(r,'bn')}</div>`);return items.join('')}
function gradeHtml(r){return r.grade?`<p class="grade-line"><strong>${esc(t('grade'))}:</strong> ${esc(r.grade)}</p>`:''}
function knownVariantsHtml(r){const a=Array.isArray(r.known_variants)?r.known_variants:[];if(!a.length&&!r.variant_note_en)return'';const baseNote=r.variant_note_en?`<p class="variant-base-note${bn()?' bn-text':''}"${bn()?' lang="bn"':''}>${esc(bn()?(r.variant_note_bn||r.variant_note_en):r.variant_note_en)}</p>`:'';const rows=a.map((v,i)=>{const vt=bn()?(v.transliteration_bn||v.transliteration_en||''):(v.transliteration_en||'');const vm=bn()?(v.meaning_bn||v.meaning_en||''):(v.meaning_en||'');const langAttrs=bn()?' lang="bn" class="bn-text"':'';const src=v.source?`<p class="variant-meta"><strong>${esc(t('variant_source'))}:</strong> ${esc(v.source)}</p>`:'';const note=v.note?`<p class="variant-meta"><strong>${esc(t('variant_note'))}:</strong> ${esc(v.note)}</p>`:'';return `<div class="variant-item">${v.context?`<strong class="variant-context">${esc(v.context)}</strong>`:''}${v.arabic?`<p lang="ar" dir="rtl" class="variant-arabic arabic-source">${esc(v.arabic)}</p>`:''}${vt?`<p${langAttrs}>${esc(vt)}</p>`:''}${vm?`<p${langAttrs}>${esc(vm)}</p>`:''}${src}${note}</div>`}).join('');return `<div class="info variant-info"><details><summary>${esc(t('known_variants'))}${a.length?` (${a.length})`:''}</summary>${baseNote}${rows}</details></div>`}
function usageContextsHtml(r){const a=Array.isArray(r.usage_contexts)?r.usage_contexts:[];if(!a.length)return'';return `<div class="info"><h4>${esc(t('usage_contexts'))}</h4><div class="usage-contexts">${a.map(x=>`<span class="badge">${esc(typeof x==='string'?x:(x.label||x.context||x.source||''))}</span>`).join('')}</div></div>`}
function relatedFamilyHtml(r){if(!r.variant_family_id)return'';const a=state.duas.filter(x=>x.id!==r.id&&x.variant_family_id===r.variant_family_id);if(!a.length)return'';return `<div class="info family-info"><h4>${esc(t('related_wordings'))}</h4><div class="family-links">${a.map(x=>`<button class="family-link" onclick="openDua('${x.id}')"><span>${esc(x.id)}</span>${esc((bn()?x.title_bn:x.title_en)||x.title_en||x.title_bn)}</button>`).join('')}</div></div>`}
function renderPersonalDetail(r){const title=(bn()?r.title_bn:r.title_en)||r.title_en||r.title_bn;return `<div class="backbar"><button onclick="state.detail=null;render()">← ${esc(t('back'))}</button><button class="soft-btn" onclick="openPersonalEditor(${jsArg(r.id)})">${esc(t('edit'))}</button></div><div class="badge-row"><span class="badge personal-badge">${esc(t('personal_dua'))}</span></div><h2 class="detail-title">${esc(title)}</h2>${r.title_en&&r.title_bn?`<p class="detail-bn${bn()?'':' bn-text'}" lang="${bn()?'en':'bn'}">${esc(bn()?r.title_en:r.title_bn)}</p>`:''}<div class="personal-authority-banner">${esc(t('personal_authority_notice'))}</div><div class="detail-grid">${optionalContent(r)}<div class="info"><h4>${esc(t('source'))}</h4><p>${esc(r.source||t('no_personal_source'))}</p>${sourceLinks(r)}</div>${(r.topics||[]).length?`<div class="info"><h4>${esc(t('topics'))}</h4><div class="badge-row">${r.topics.map(x=>`<span class="badge">${esc(x)}</span>`).join('')}</div></div>`:''}</div>`}
function renderDetail(r){if(!r)return `<div class="empty"><h3>${esc(t('no_results'))}</h3></div>`;if(r.origin==='personal')return renderPersonalDetail(r);const title=(bn()?r.title_bn:r.title_en)||r.title_en||r.title_bn,alt=(bn()?r.title_en:r.title_bn)||'';return `<div class="backbar"><button onclick="state.detail=null;render()">← ${esc(t('back'))}</button><button class="${state.saved.has(r.id)?'primary-btn':'soft-btn'}" onclick="toggleSave('${r.id}')">${esc(state.saved.has(r.id)?t('unsave'):t('save'))}</button></div><div class="badge-row"><span class="badge prov">${esc(prov(r))}</span><span class="badge">${esc(r.id)}</span></div><h2 class="detail-title">${esc(title)}</h2>${alt?`<p class="detail-bn${bn()?'':' bn-text'}" lang="${bn()?'en':'bn'}">${esc(alt)}</p>`:''}<div class="detail-grid">${canonicalContent(r)}<div class="info source-card"><h4>${esc(t('source'))}</h4><p>${esc(r.source)}</p>${gradeHtml(r)}${sourceLinks(r)}${quranCreditsHtml(r)}</div>${relatedFamilyHtml(r)}${knownVariantsHtml(r)}${usageContextsHtml(r)}${r.jurisprudential_usage_en?`<div class="info"><h4>${esc(t('jurisprudence'))}</h4><p>${esc(bn()?(r.jurisprudential_usage_bn||r.jurisprudential_usage_en):r.jurisprudential_usage_en)}</p></div>`:''}${(r.topics||[]).length?`<div class="info"><h4>${esc(t('topics'))}</h4><div class="badge-row">${r.topics.map(x=>`<span class="badge">${esc(x)}</span>`).join('')}</div></div>`:''}</div>`}
function prefsSnapshot(){return{theme:state.theme,lang:state.lang,arabicScript:state.arabicScript,display:{...state.display}}}
function backupSaved(){return [...state.savedRecords.values()].map(cleanSavedRecord).filter(Boolean).sort((a,b)=>b.savedAt-a.savedAt)}
function backupPersonal(){return [...state.personalDuas.values()].map(cleanPersonalRecord).filter(Boolean).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0))}
function buildPersonalBackup(){return{format:BACKUP_FORMAT,version:BACKUP_VERSION,createdAt:new Date().toISOString(),app:'DuaOnDevice',saved:backupSaved(),personalDuas:backupPersonal(),preferences:prefsSnapshot()}}
function downloadPersonalBackup(){const data=buildPersonalBackup(),blob=new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`DuaOnDevice-Personal-Backup-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);toast(t('backup_created'))}
function validatePersonalBackup(x){if(!x||x.format!==BACKUP_FORMAT||![1,2].includes(x.version)||!Array.isArray(x.saved))throw new Error(t('backup_invalid'));if(x.saved.length>1000)throw new Error(t('backup_invalid'));const saved=x.saved.map(cleanSavedRecord);if(saved.some(x=>!x))throw new Error(t('backup_invalid'));const personalRaw=x.version>=2?(x.personalDuas||[]):[];if(!Array.isArray(personalRaw)||personalRaw.length>1000)throw new Error(t('backup_invalid'));const personalDuas=personalRaw.map(cleanPersonalRecord);if(personalDuas.some(x=>!x))throw new Error(t('backup_invalid'));const ids=new Set();for(const r of personalDuas){if(ids.has(r.id))throw new Error(t('backup_invalid'));ids.add(r.id)}const p=x.preferences||{},preferences={};if(themeChrome[p.theme])preferences.theme=p.theme;if(['en','bn'].includes(p.lang))preferences.lang=p.lang;if(['indopak','uthmani'].includes(p.arabicScript))preferences.arabicScript=p.arabicScript;const display={...DEFAULT_DISPLAY};if(p.display&&typeof p.display==='object'){for(const k of Object.keys(DEFAULT_DISPLAY))if(typeof p.display[k]==='boolean')display[k]=p.display[k]}preferences.display=display;return{saved,personalDuas,preferences,createdAt:String(x.createdAt||''),sourceVersion:x.version}}
async function restorePersonalBackup(input){const file=input?.files?.[0];if(!file)return;try{if(file.size>10_000_000)throw new Error(t('backup_invalid'));const data=validatePersonalBackup(JSON.parse(await file.text()));if(!confirm(t('restore_confirm_v2'))){input.value='';return}await replaceSavedRecords(data.saved);await replacePersonalRecords(data.personalDuas);localStorage.setItem('dua-theme',data.preferences.theme||'day');localStorage.setItem('dua-lang',data.preferences.lang||'en');localStorage.setItem('dua-arabic-script',data.preferences.arabicScript||'indopak');localStorage.setItem('dua-display',JSON.stringify(data.preferences.display||DEFAULT_DISPLAY));input.value='';location.reload()}catch(e){input.value='';toast(e?.message||t('backup_invalid'))}}
function render(){let body;if(state.detail){body=renderDetail(getRecord(state.detail))}else if(state.tab==='search')body=renderSearch();else if(state.tab==='browse')body=renderBrowse();else if(state.tab==='saved')body=renderSaved();else if(state.tab==='guide')body=renderGuide();else body=renderSettings();$('#app').innerHTML=shell(body)}
function openDua(id){if(!getRecord(id))return;state.detail=id;state.personalEditorId=null;render();setTimeout(()=>$('.workspace')?.scrollTo(0,0),0)}
function go(tab){state.tab=tab;state.detail=null;state.editSavedId=null;state.personalEditorId=null;render()}
function toast(msg){const e=document.createElement('div');e.className='toast';e.textContent=msg;document.body.appendChild(e);setTimeout(()=>e.remove(),1500)}
function registerSW(){if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{})}
window.openDua=openDua;window.toggleSave=toggleSave;window.go=go;window.applyTheme=applyTheme;window.setLang=setLang;window.setArabicScript=setArabicScript;window.render=render;window.renderResults=renderResults;window.editSaved=editSaved;window.cancelSavedEdit=cancelSavedEdit;window.savePersonalNote=savePersonalNote;window.clearPersonalNote=clearPersonalNote;window.requestPersistentStorage=requestPersistentStorage;window.downloadPersonalBackup=downloadPersonalBackup;window.restorePersonalBackup=restorePersonalBackup;window.setBrowseOrigin=setBrowseOrigin;window.openPersonalEditor=openPersonalEditor;window.closePersonalEditor=closePersonalEditor;window.savePersonalDua=savePersonalDua;window.removePersonalDua=removePersonalDua;window.prepareNeuralSearch=prepareNeuralSearch;window.cancelNeuralPreparation=cancelNeuralPreparation;window.clearNeuralSearch=clearNeuralSearch;window.onSearchInput=onSearchInput;window.exportE5PrecomputedIndex=exportE5PrecomputedIndex;window.clearSearchQuery=clearSearchQuery;window.state=state;boot().catch(e=>{$('#app').innerHTML=`<div style="padding:30px;font-family:system-ui">DuaOnDevice could not start.<br><small>${esc(e.message)}</small></div>`});
